<?php
namespace Modules\AiReception\Native;
/** Tenant encrypted workflow state, linked to an already authorized conversation. */
final class DialogueSession {
 private function db(int $conversation,int $person){app(Access::class)->require('aireception','conversations');$db=app('db')->connection('tenant');if(!$db->table('aireception_conversations')->where('id',$conversation)->where('person_id',$person)->exists())abort(404);return $db;}
 public function load(int $conversation,int $person):array {$db=$this->db($conversation,$person);$row=$db->table('aireception_dialogue_states')->where('conversation_id',$conversation)->where('business_id',app(Access::class)->business())->where('person_id',$person)->first();return $row&&$row->expires_at>date('Y-m-d H:i:s')?app('encrypter')->decrypt($row->encrypted_state):[];}
 public function save(int $conversation,int $person,array $state):void {$db=$this->db($conversation,$person);$now=date('Y-m-d H:i:s');$db->table('aireception_dialogue_states')->updateOrInsert(['conversation_id'=>$conversation],['business_id'=>app(Access::class)->business(),'person_id'=>$person,'encrypted_state'=>app('encrypter')->encrypt($state),'expires_at'=>date('Y-m-d H:i:s',time()+86400),'updated_at'=>$now]);}
 public function begin(int $conversation,int $person,string $text,array $selection):array {$old=$this->load($conversation,$person);$next=DialogueState::advance($old,$selection,$text);$next['identity']=['business_id'=>app(Access::class)->business(),'person_id'=>$person,'actor_id'=>(int)auth('web')->id()];$sites=$this->db($conversation,$person)->table('establishments')->pluck('id')->all();if(count($sites)===1)$next['site_id']=(int)$sites[0];if(!empty($old['pending'])&&empty($next['pending'])){$db=$this->db($conversation,$person);$db->table('aireception_pending_confirmations')->where('conversation_id',$conversation)->delete();if(isset($old['pending']['token_hash']))$db->table('aireception_booking_drafts')->where('business_id',app(Access::class)->business())->where('conversation_id',$conversation)->where('token_hash',$old['pending']['token_hash'])->whereNull('result')->update(['expires_at'=>date('Y-m-d H:i:s',time()-1)]);}$this->save($conversation,$person,$next);return $next;}
 public function result(int $conversation,int $person,string $tool,array $reply):void {$state=$this->load($conversation,$person);if($tool==='availability'&&isset($reply['slots'])){$state['offered']=array_column($reply['slots'],'start');$state['phase']='choosing_slot';}if(isset($reply['proposal'])){$hash=hash('sha256',$reply['proposal']['confirmation_token']);$state['pending']=['action'=>$reply['proposal']['action']??'book','expires_at'=>$reply['proposal']['expires_at'],'token_hash'=>$hash];$this->db($conversation,$person)->table('aireception_booking_drafts')->where('business_id',app(Access::class)->business())->where('actor_id',(int)auth('web')->id())->where('token_hash',$hash)->update(['conversation_id'=>$conversation]);$state['phase']='awaiting_confirmation';}if(isset($reply['booking'])){$state['booking_id']=(int)$reply['booking']['id'];$state['phase']=$reply['booking']['status'];$state['pending']=null;}if(!empty($reply['handoff']))$state['phase']='human';$this->save($conversation,$person,$state);}
 public function purgeExpired():int {app(Access::class)->require('aireception','configure');return app('db')->connection('tenant')->table('aireception_dialogue_states')->where('business_id',app(Access::class)->business())->where('expires_at','<=',date('Y-m-d H:i:s'))->delete();}
 public function recoverable(array $state=[]):array {
  $questions=['booking_id'=>'¿Cuál es el número de la cita que quieres modificar?','service_id'=>'¿Qué servicio necesitas?','professional_id'=>'¿Con qué profesional prefieres atenderte?','day'=>'¿Qué fecha prefieres?','start'=>'¿Qué horario de los disponibles prefieres?'];
  foreach($state['missing']??[] as $key)if(isset($questions[$key]))return ['reply'=>$questions[$key].' Todavía no se ha confirmado ninguna operación.','needs_clarification'=>true];
  return ['reply'=>'No tengo un horario verificado para esa operación. Consulta la disponibilidad y elige una opción; aún no se ha confirmado nada.','needs_clarification'=>true];
 }
}
